import json

# Read current JSON content
with open('/app/incident_report.json', 'r') as f:
    report = json.load(f)

# Update JSON to match required format exactly
# Ensure proper formatting of all fields

# 1. Summary section
report['summary'] = {
    "total_files": report['summary']['total_files'],
    "total_exceptions": report['summary']['total_exceptions'],
    "critical_failures": report['summary']['critical_failures'],
    "most_common_exception": report['summary']['most_common_exception']
}

# 2. Log levels section - ensure proper format
report['log_levels'] = {
    "FATAL": {
        "count": report['log_levels']['FATAL']['count'],
        "percentage": round(report['log_levels']['FATAL']['percentage'], 1)
    },
    "ERROR": {
        "count": report['log_levels']['ERROR']['count'],
        "percentage": round(report['log_levels']['ERROR']['percentage'], 1)
    },
    "WARN": {
        "count": report['log_levels']['WARN']['count'],
        "percentage": round(report['log_levels']['WARN']['percentage'], 1)
    },
    "INFO": {
        "count": report['log_levels']['INFO']['count'],
        "percentage": round(report['log_levels']['INFO']['percentage'], 1)
    },
    "DEBUG": {
        "count": report['log_levels']['DEBUG']['count'],
        "percentage": round(report['log_levels']['DEBUG']['percentage'], 1)
    }
}

# 3. Exception types - ensure proper format
# Sort by count descending (already done)
report['exception_types'] = sorted(
    report['exception_types'], 
    key=lambda x: -x['count']
)

# 4. Stack traces - ensure proper format
# Already populated from top 3 exception classes

# Write updated JSON
with open('/app/incident_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print("JSON file updated successfully!")
EOF"}

